async function swapMask(imageUrl) {
  if (!_hasWebGL || !THREE || !facePoints) return;
  try {
    const img = new Image();
    img.crossOrigin = 'anonymous';
    await new Promise((res, rej) => { img.onload = res; img.onerror = rej; img.src = imageUrl; });
    const tmp = document.createElement('canvas');
    tmp.width = tmp.height = 512;
    tmp.getContext('2d').drawImage(img, 0, 0, 512, 512);
    const nd = sampleDepthMapGrid(tmp, FACE_GRID_COLS, FACE_GRID_ROWS);
    const ng = new THREE.BufferGeometry();
    ng.setAttribute('position',  new THREE.BufferAttribute(nd.home, 3));
    ng.setAttribute('scatter',   new THREE.BufferAttribute(nd.scatter, 3));
    ng.setAttribute('subjectFrom', new THREE.BufferAttribute(nd.home.slice(), 3));
    ng.setAttribute('semanticStage', new THREE.BufferAttribute(new Float32Array(nd.seeds.length), 1));
    ng.setAttribute('seed',      new THREE.BufferAttribute(nd.seeds, 1));
    ng.setAttribute('curvature', new THREE.BufferAttribute(nd.curvature, 1));
    ng.setAttribute('boundary',  new THREE.BufferAttribute(nd.boundary, 1));
    ng.setAttribute('zone',      new THREE.BufferAttribute(nd.zone, 1));
    facePoints.geometry.dispose();
    facePoints.geometry = ng;
    morphCurrent = 0; morphTarget = 1.0;
    mouthPool = null; eyePool = null;
    initSemanticPools();
    State.flash = 0.5; State.pulse = 0.8;
    if (uiStatus) uiStatus.textContent = 'mask loaded';
  } catch (_) {
    if (uiStatus) uiStatus.textContent = 'mask load failed';
  }
}

function faceFieldSample(index, salt = 0) {
  const value = Math.sin(index * 12.9898 + salt * 78.233) * 43758.5453;
  return value - Math.floor(value);
}

let frameLoopActive = false;
let frameRequest = null;
let frameRequestedAt = 0;
let watchdogTimer = null;
let watchdogLastFrames = -1;
let pumpTimer = null;
let naturalRafSeen = false;

function queueFaceFrame() {
  if (State.hidden || document.hidden || frameRequest !== null) return;
  frameLoopActive = true;
  frameRequestedAt = performance.now();
  frameRequest = requestAnimationFrame(t => {
    frameRequest = null;
    naturalRafSeen = true;
    stopFramePump();
    frame(t);
  });
}

function ensureFrameLoop() {
  if (State.hidden || document.hidden) return;
  queueFaceFrame();
  armFrameLoopWatchdog();
}

function stopFramePump() {
  if (pumpTimer === null) return;
  clearInterval(pumpTimer);
  pumpTimer = null;
}

function suspendFaceFrames() {
  if (frameRequest !== null) cancelAnimationFrame(frameRequest);
  frameRequest = null;
  frameLoopActive = false;
  stopFramePump();
}

function armFrameLoopWatchdog() {
  if (watchdogTimer !== null) return;
  watchdogTimer = setInterval(() => {
    if (State.hidden || document.hidden) {
      suspendFaceFrames();
      watchdogLastFrames = _dbgFrames;
      return;
    }
    if (naturalRafSeen) {
      naturalRafSeen = false;
      stopFramePump();
    } else if (_dbgFrames === watchdogLastFrames) {
      // Replace a stalled callback rather than accumulating concurrent loops.
      if (frameRequest !== null && performance.now() - frameRequestedAt >= 2000) {
        cancelAnimationFrame(frameRequest);
        frameRequest = null;
      }
      queueFaceFrame();
      if (pumpTimer === null) pumpTimer = setInterval(() => {
        if (!State.hidden && !document.hidden) frame(performance.now());
      }, 40);
    }
    watchdogLastFrames = _dbgFrames;
  }, 2000);
}

document.addEventListener("visibilitychange", () => {
  if (document.hidden) suspendFaceFrames();
});
window.addEventListener("pagehide", () => {
  suspendFaceFrames();
  if (watchdogTimer !== null) clearInterval(watchdogTimer);
  watchdogTimer = null;
});
window.addEventListener("pageshow", ensureFrameLoop);

// WebGL context loss is the silent permanent-black-canvas case: the browser
// (usually a phone under GPU memory pressure) revokes the context, every
// renderer.render() after that is a no-op, and NOTHING throws — the loop keeps
// ticking, dbgFrames keeps counting, the face is just gone. contextlost fires
// on the CANVAS (the old vision-layer listeners sat on window and never ran).
// preventDefault() is what tells the browser we want a restore; on restore,
// THREE re-uploads GL state lazily on the next render.
if (typeof cv !== 'undefined' && cv?.addEventListener) {
  cv.addEventListener('webglcontextlost', (e) => {
    e.preventDefault();
    if (uiStatus) uiStatus.textContent = 'gpu context lost — recovering…';
  }, false);
  cv.addEventListener('webglcontextrestored', () => {
    if (uiStatus && uiStatus.textContent.startsWith('gpu context lost')) uiStatus.textContent = '';
    try { resize(); } catch (err) { window.MASTER_LOG?.warn?.("face_runtime:webgl_context_restored", err); }
    ensureFrameLoop();
  }, false);
}

